451	function cmdCtxGenerate(args) {
452	  const ctxDir = path.join(WORKSPACE_ROOT, '.context');
453	  if (fs.existsSync(ctxDir)) {
454	    fs.rmSync(ctxDir, { recursive: true, force: true });
455	    log('Cleaned .context/', 'dim');
456	  }
457	  const result = spawnSync('ctx', ['generate', ...args], {
458	    cwd: WORKSPACE_ROOT,
459	    stdio: 'inherit',
460	    shell: IS_WIN,
461	  });
462	  if (result.status !== 0) {
463	    log('\n\u2717 ctx generate exited with code ' + (result.status ?? 1), 'red');
464	    process.exit(result.status ?? 1);
465	  }
466	  sh('node', [path.join(SCRIPTS_DIR, 'normalize-ctx-paths.js'), ctxDir], { cwd: WORKSPACE_ROOT });
467	  fs.writeFileSync(path.join(ctxDir, 'generated-at.txt'), new Date().toISOString() + '\n');
468	  const agentsMd = path.join(WORKSPACE_ROOT, 'AGENTS.md');
469	  const claudeMd = path.join(WORKSPACE_ROOT, 'CLAUDE.md');
470	  if (fs.existsSync(agentsMd)) {
471	    const agentsContent = fs.readFileSync(agentsMd, 'utf8');
472	    const header = '<!-- NOTE: This file is generated automatically from AGENTS.md whenever CTX documents are updated -->\n\n';
473	    fs.writeFileSync(claudeMd, header + agentsContent, 'utf8');
474	    log('Synced AGENTS.md \u2192 CLAUDE.md', 'dim');
475	  } else {
476	    log('\u26a0 AGENTS.md not found \u2014 CLAUDE.md not updated', 'yellow');
477	  }
478	}
